viewLatenessMergesWithInherited.sql:
CREATE TABLE t(ts INT NOT NULL LATENESS 1);
LATENESS v.ts 10;
CREATE LOCAL VIEW v AS SELECT ts FROM t;
CREATE VIEW w AS SELECT * FROM v;

viewLatenessKeepsInheritedWaterline.sql:
CREATE TABLE t(ts INT NOT NULL LATENESS 2, x INT NOT NULL);
LATENESS v.x 1;
CREATE LOCAL VIEW v AS SELECT ts, x FROM t;
CREATE VIEW w AS SELECT * FROM v;

viewLatenessTimestampMerge.sql:
CREATE TABLE t(ts TIMESTAMP NOT NULL LATENESS INTERVAL 1 HOUR, x INT);
LATENESS v.ts INTERVAL 1 DAY;
LATENESS v.x 1;
CREATE LOCAL VIEW v AS SELECT ts, x FROM t;
CREATE VIEW w AS SELECT * FROM v;

gcKeyLateness.sql:
CREATE TABLE t (
    ts BIGINT NOT NULL PRIMARY KEY LATENESS 100,
    v INT
);
CREATE VIEW vw AS SELECT * FROM t;

gcCompositeKeyLateness.sql:
CREATE TABLE t (
    id INT NOT NULL,
    ts BIGINT NOT NULL LATENESS 100,
    extra BIGINT NOT NULL LATENESS 100,
    v INT,
    PRIMARY KEY (id, ts)
);
CREATE VIEW vw AS SELECT * FROM t;
